// Then we need to apply this transition k = m/2 times? No.
// Total length = n * m.
// The sequence consists of m blocks of size n.
// So we apply transition matrix T, m times.
// Initial state: balance 0, cost 0.
// Final state: balance 0.
// So we compute T^m (min-plus power).
// Result = (T^m)[0][0].

// Wait, m can be up to 10^7. log2(10^7) ~ 24.
// Matrix size (n+1) <= 21.
// Multiplication: O(21^3) = 9261.
// 24 * 9261 ~ 222k operations. Extremely fast.

$INF = 1e18;
$N_state = $n + 1; // balances 0..n

// Build Base Transition Matrix T
// T[i][j] = cost from balance i to balance j after n brackets
$T = [];
for ($i = 0; $i < $N_state; $i++) {
    $T[$i] = array_fill(0, $N_state, $INF);
}

// Compute T by simulating one block for each start balance
// Optimization: Run one DP that tracks cost for all start balances simultaneously?
// Since n is small (20), just loop start balances.
for ($start_bal = 0; $start_bal <= $n; $start_bal++) {
    $dp = array_fill(0, $N_state, $INF);
    $dp[$start_bal] = 0;

    for ($pos = 0; $pos < $n; $pos++) {
        $new_dp = array_fill(0, $N_state, $INF);
        $cost_o = $a[$pos];
        $cost_c = $b[$pos];
        for ($bal = 0; $bal <= $n; $bal++) {
            $val = $dp[$bal];
            if ($val === $INF) continue;
            // Open
            if ($bal + 1 <= $n) {
                $new_dp[$bal + 1] = min($new_dp[$bal + 1], $val + $cost_o);
            }
            // Close
            if ($bal - 1 >= 0) {
                $new_dp[$bal - 1] = min($new_dp[$bal - 1], $val + $cost_c);
            }
        }
        $dp = $new_dp;
    }
    // dp now holds costs to reach each end balance
    for ($end_bal = 0; $end_bal <= $n; $end_bal++) {
        $T[$start_bal][$end_bal] = $dp[$end_bal];
    }
}

// Min-plus matrix multiplication
function minPlusMultiply($A, $B, $size, $INF) {
    $C = [];
    for ($i = 0; $i < $size; $i++) {
        $C[$i] = array_fill(0, $size, $INF);
        for ($k = 0; $k < $size; $k++) {
            $aik = $A[$i][$k];
            if ($aik === $INF) continue;
            // Unroll inner loop for speed? PHP loops are slow.
            // Standard triple loop.
            for ($j = 0; $j < $size; $j++) {
                $bkj = $B[$k][$j];
                if ($bkj === $INF) continue;
                $sum = $aik + $bkj;
                if ($sum < $C[$i][$j]) {
                    $C[$i][$j] = $sum;
                }
            }
        }
    }
    return $C;
}

