// Identity matrix for min-plus: 0 on diagonal, INF elsewhere
$Res = [];
for ($i = 0; $i < $size; $i++) {
    $Res[$i] = array_fill(0, $size, $INF);
    $Res[$i][$i] = 0;
}

$Base = $T;

