    if ($power & 1) {
        $Res = minPlusMultiply($Res, $Base, $size, $INF);
    }
    if ($power > 1) { // Avoid squaring on last iteration if not needed, though loop condition handles it
        $Base = minPlusMultiply($Base, $Base, $size, $INF);
    }
    $power >>= 1;
}

// Answer is Res[0][0] (start bal 0, end bal 0 after m blocks)
$ans = $Res[0][0];
echo $ans . "\n";
